// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    Receiver r;

    function setUp() public {
        r = new Receiver();
        vm.prank(address(r));
        c = new SimpleWallet();
    }

    function testFuzz_property(uint256 amount) public {
        // admissible domain: any positive, realistic wei amount the contract can be funded with
        amount = bound(amount, 1, 1 ether * 1_000_000);

        // fund the contract with the fuzzed amount
        vm.deal(address(c), amount);
        vm.assume(address(c).balance == amount);

        // owner (a plain receiver with a payable receive) drains everything
        vm.prank(address(r));
        c.withdrawAll();

        // general rule: withdrawAll always empties the contract's balance
        assertTrue(address(c).balance == 0);
    }
}

contract Receiver {
    receive() external payable {}
}
